/* Banque de questions supplémentaires : français, chapitres 1 à 9 (phonologie, classes, fonctions, phrase, conjugaison, valeurs des temps, accords, homophones, lexique) */
window.BANK = window.BANK || {};

BANK['francais/1'] = [
  { q: "Combien de phonèmes dans le mot « chanteur » ?", answers: ["5", "cinq"], expl: "On écoute : [ʃ] [ɑ̃] [t] [œ] [ʁ] → <b>5 phonèmes</b>. Le piège : compter les lettres (8). « ch », « an » et « eu » sont des graphèmes de deux lettres pour un seul son." },
  { q: "Combien de phonèmes dans le mot « moustique » ?", answers: ["6", "six"], expl: "[m] [u] [s] [t] [i] [k] → <b>6 phonèmes</b>. « ou » et « qu » ne font chacun qu’un son, et le e final est muet : il ne compte pas." },
  { q: "Dans quel mot la lettre x transcrit-elle les deux phonèmes [gz] ?", choices: ["taxi", "exemple", "deux", "soixante"], answer: 1, expl: "« exemple » se dit [ɛgzɑ̃pl] : le x vaut [gz]. Dans « taxi », il vaut [ks] ; dans « soixante », [s] ; dans « deux », il est muet. Une même lettre peut donc transcrire des sons très différents." },
  { q: "Quel mot contient une semi-voyelle ?", choices: ["lune", "lion", "loup", "lent"], answer: 1, expl: "« lion » se dit [ljɔ̃] : le i devant une voyelle devient la semi-voyelle [j]. Les semi-voyelles du français sont [j], [w] et [ɥ] ; les autres mots ne contiennent que des voyelles pleines." },
  { q: "Quel graphème transcrit le phonème [ɛ̃] ?", choices: ["« ein » (plein)", "« an » (blanc)", "« on » (bon)", "« eu » (feu)"], answer: 0, expl: "[ɛ̃] s’écrit in, im, ain, aim, ein, en (chien)… « an » transcrit [ɑ̃], « on » [ɔ̃] et « eu » [ø]. Un même phonème peut avoir de nombreux graphèmes : c’est une grosse difficulté pour les élèves." },
  { type: 'vf', q: "Vrai ou faux : dans « oignon », le graphème « oi » se prononce [wa], comme dans « roi ».", answer: 1, expl: "Faux : « oignon » se dit [ɔɲɔ̃] ; ici « oi » vaut [ɔ]. C’est d’ailleurs pour cela que l’orthographe rectifiée de 1990 propose « ognon »." },
  { q: "Combien de syllabes orales dans « mercredi » ?", answers: ["3", "trois"], expl: "mer-cre-di → <b>3 syllabes</b>. Chaque syllabe contient une seule voyelle prononcée : [ɛ], [ə], [i]. Tape dans tes mains en disant le mot, comme on le fait en maternelle." },
  { q: "Combien de syllabes <b>écrites</b> dans « fenêtre » ?", choices: ["1", "2", "3", "4"], answer: 2, expl: "À l’écrit on découpe fe-nê-tre → <b>3 syllabes écrites</b>, en comptant le e muet final. À l’oral, on n’en entend souvent que 2 ([fə-nɛtʁ]) : syllabe orale et syllabe écrite ne coïncident pas toujours." },
  { q: "Dans « tortue » (tor-tue), la première syllabe est :", choices: ["ouverte", "fermée", "muette"], answer: 1, expl: "« tor » se termine par une consonne prononcée [ʁ] : c’est une syllabe <b>fermée</b>. Une syllabe ouverte finit par une voyelle prononcée, comme « tue »." },
  { type: 'vf', q: "Vrai ou faux : [p] et [b] se prononcent de la même façon avec la bouche ; seule la vibration des cordes vocales les distingue.", answer: 0, expl: "Vrai : [p] est une consonne <b>sourde</b> (sans vibration), [b] sa correspondante <b>sonore</b>. Pose ta main sur ta gorge pour sentir la différence : c’est pour cela que les élèves les confondent." },
  { q: "Quelle paire de mots est une <b>paire minimale</b> (deux mots qui ne diffèrent que par un seul phonème) ?", choices: ["poule / boule", "poule / poules", "vert / verre", "chat / chats"], answer: 0, expl: "« poule / boule » ne diffèrent que par [p]/[b] : cela prouve que ce sont deux phonèmes distincts. « vert / verre » se prononcent exactement pareil, et le pluriel de « poules » ou « chats » ne s’entend pas." },
  { q: "Quel symbole de l’API note le son entendu dans « loup » ? (avec les crochets)", answers: ["[u]", "u"], expl: "Le son « ou » se note <b>[u]</b>. Piège classique : [y] ne note pas « ou » mais le son de « lune »." },
  { q: "Dans « guitare », quel est le rôle de la lettre u ?", choices: ["Elle transcrit le son [y]", "Elle forme avec g le graphème « gu », qui donne [g] devant i", "Elle est muette et ne sert à rien"], answer: 1, expl: "Devant e ou i, g se lit [ʒ] (girafe) ; on ajoute u pour garder le son [g] : « gu » est un seul graphème. Le u n’est pas prononcé, mais il a un rôle de lecture." },
  { q: "Un élève de CP écrit « mézon » pour « maison ». Comment analyser cette erreur ?", choices: ["Il a mal entendu les sons du mot", "Son écriture est phonétiquement plausible : il a bien transcrit les sons, mais pas avec les graphèmes de la norme", "C’est une erreur d’accord grammatical"], answer: 1, expl: "« mézon » se lit bien [mɛzɔ̃] / [mezɔ̃] : l’élève maîtrise la correspondance sons-lettres. Il lui reste à mémoriser l’orthographe lexicale (ai pour [ɛ], s entre deux voyelles pour [z]). C’est une erreur plutôt encourageante." },
  { q: "Un élève écrit « fache » au lieu de « vache ». Quelle confusion fait-il ?", choices: ["Une confusion de lettres en miroir", "Une confusion entre une consonne sourde [f] et sa sonore [v]", "L’oubli d’une lettre muette"], answer: 1, expl: "[f] et [v] se prononcent au même endroit ; seule la vibration des cordes vocales change. b/d ou p/q, eux, sont des confusions visuelles de lettres en miroir." },
  { q: "Combien de phonèmes dans le mot « examen » ?", answers: ["6", "six"], expl: "[ɛ] [g] [z] [a] [m] [ɛ̃] → <b>6 phonèmes</b>. Attention : le x vaut ici deux phonèmes [gz], et « en » final se lit [ɛ̃] (comme dans « chien »)." },
  { type: 'vf', q: "Vrai ou faux : dans « hibou », la lettre h transcrit un phonème.", answer: 1, expl: "Faux : en français, le h ne se prononce jamais. Le h dit « aspiré » de « hibou » empêche seulement la liaison et l’élision (le hibou, les | hiboux)." },
  { q: "Quel mot contient le phonème [ɔ̃] ?", choices: ["nombre", "nommer", "bonne", "lent"], answer: 0, expl: "« nombre » se dit [nɔ̃bʁ]. Dans « nommer » et « bonne », le o est suivi d’une consonne double prononcée : on entend [ɔ] puis [m] ou [n], sans nasale. « lent » contient [ɑ̃]." },
  { q: "Combien de phonèmes dans le mot « soixante » ?", answers: ["6", "six"], expl: "[s] [w] [a] [s] [ɑ̃] [t] → <b>6 phonèmes</b>. « oi » donne deux phonèmes [wa], le x se lit [s] et le e final est muet." },
  { type: 'vf', q: "Vrai ou faux : la conscience phonologique ne peut se travailler qu’une fois que l’enfant sait lire.", answer: 1, expl: "Faux : elle se travaille <b>dès la maternelle</b>, à l’oral (comptines, rimes, frapper les syllabes, trouver le son commun). Elle prépare la lecture et en est un des meilleurs prédicteurs." }
];

BANK['francais/2'] = [
  { q: "Nature de « en » dans « Il en a besoin » :", choices: ["pronom personnel", "préposition", "adverbe", "déterminant"], answer: 0, expl: "Placé devant le verbe, « en » remplace un groupe introduit par de (il a besoin <i>de cela</i>) : c’est un <b>pronom personnel</b>. Devant un nom (« en France »), ce serait une préposition." },
  { q: "Nature de « des » dans « J’ai acheté des cerises » :", choices: ["article indéfini", "article contracté", "article partitif", "préposition"], answer: 0, expl: "« des » est ici le pluriel de « une » (une cerise → des cerises) : <b>article indéfini</b>. Il serait article contracté (de + les) dans « le goût des cerises »." },
  { q: "Nature de « tous » dans « Ils sont tous venus » :", choices: ["déterminant indéfini", "pronom indéfini", "adverbe", "adjectif qualificatif"], answer: 1, expl: "« tous » n’introduit aucun nom ici, il représente « ils » : c’est un <b>pronom indéfini</b> (on prononce d’ailleurs le s : [tus]). Dans « tous les jours », il serait déterminant." },
  { q: "Nature de « bien » dans « Ce bien appartient à ma famille » :", choices: ["adverbe", "nom commun", "adjectif", "préposition"], answer: 1, expl: "« bien » est précédé du déterminant « ce » et désigne une chose possédée : c’est un <b>nom commun</b>. Dans « il chante bien », ce serait un adverbe. Regarde toujours l’entourage du mot." },
  { q: "Nature de « que » dans « Que cette forêt est belle ! » :", choices: ["pronom relatif", "conjonction de subordination", "adverbe exclamatif", "pronom interrogatif"], answer: 2, expl: "Dans une phrase exclamative, « que » signifie « comme, à quel point » et porte sur l’adjectif belle : c’est un <b>adverbe exclamatif</b>. Il n’y a ni antécédent (relatif) ni verbe introducteur (conjonction)." },
  { q: "Nature de « parce que » :", choices: ["conjonction de coordination", "locution conjonctive de subordination", "adverbe", "préposition"], answer: 1, expl: "« parce que » introduit une proposition subordonnée (de cause) : c’est une <b>conjonction de subordination</b> en deux mots (locution). Ne la confonds pas avec « car », conjonction de coordination." },
  { q: "Quelle est la nature du mot « chez » ?", answers: ["préposition", "une préposition"], expl: "« chez » introduit un complément (chez mon oncle) et ne varie jamais : c’est une <b>préposition</b>, comme à, de, par, pour, sans, dans…" },
  { q: "Quelle est la nature du mot « hélas » ?", answers: ["interjection", "une interjection"], expl: "« hélas » exprime une émotion (le regret) et forme à lui seul un énoncé : c’est une <b>interjection</b>, mot invariable." },
  { q: "Combien de déterminants dans : « Mes deux frères ont vendu leur vieille voiture à ce garagiste. » ?", answers: ["4", "quatre"], expl: "mes (possessif), deux (numéral), leur (possessif, devant le nom voiture), ce (démonstratif) → <b>4</b>. Le piège : oublier le numéral « deux », ou compter « vieille », qui est un adjectif." },
  { q: "Lequel de ces mots est invariable ?", choices: ["gentil", "celui", "malgré", "tienne"], answer: 2, expl: "« malgré » est une préposition : il ne change jamais de forme. « gentil » (gentille), « celui » (celle, ceux) et « tienne » (tien, tiens) varient en genre et/ou en nombre." },
  { q: "Dans « Le rouge lui va bien », « rouge » est :", choices: ["un adjectif qualificatif", "un nom commun", "un adverbe"], answer: 1, expl: "Précédé du déterminant « le » et sujet du verbe, « rouge » désigne ici une couleur : c’est un adjectif employé comme <b>nom</b> (on dit qu’il est nominalisé). La nature dépend de l’emploi dans la phrase." },
  { q: "Nature de « lequel » dans « Voici l’outil avec lequel il travaille » :", choices: ["pronom interrogatif", "pronom relatif", "déterminant", "conjonction de subordination"], answer: 1, expl: "« lequel » a un antécédent (l’outil) et introduit une subordonnée relative : c’est un <b>pronom relatif</b>. Dans « Lequel veux-tu ? », il serait interrogatif." },
  { type: 'vf', q: "Vrai ou faux : un adverbe peut modifier le sens d’un adjectif.", answer: 0, expl: "Vrai : dans « très grand » ou « trop lourd », l’adverbe modifie l’adjectif. Il peut aussi porter sur un verbe, un autre adverbe ou toute la phrase (heureusement, …)." },
  { type: 'vf', q: "Vrai ou faux : le pronom personnel « leur » prend un s quand il remplace un groupe au pluriel.", answer: 1, expl: "Faux : le pronom « leur » est déjà le pluriel de « lui » ; il ne prend <b>jamais</b> de s (je leur parle). Seul le déterminant possessif s’accorde : leurs cahiers." },
  { type: 'vf', q: "Vrai ou faux : « aucun » peut être un déterminant.", answer: 0, expl: "Vrai : dans « aucun élève n’est absent », il introduit le nom élève : <b>déterminant indéfini</b>. Dans « aucun n’est venu », il est pronom indéfini." },
  { type: 'vf', q: "Vrai ou faux : un pronom remplace toujours un nom déjà cité dans le texte.", answer: 1, expl: "Faux : « je », « tu », « nous » désignent les personnes qui parlent, sans rien remplacer, et « personne », « rien », « on » ne reprennent aucun nom. Le pronom peut <b>représenter</b> ou <b>désigner</b>." },
  { q: "Quelle est la nature de « celle-ci » ?", answers: ["pronom démonstratif", "un pronom démonstratif"], expl: "« celle-ci » remplace un nom féminin en le montrant (« Quelle robe ? Celle-ci. ») : <b>pronom démonstratif</b>. Ne le confonds pas avec le déterminant démonstratif « cette », qui est suivi d’un nom." },
  { q: "Nature précise de « quelques » dans « J’ai invité quelques amis » ?", answers: ["déterminant indéfini", "un déterminant indéfini"], expl: "« quelques » introduit le nom amis et exprime une quantité imprécise : <b>déterminant indéfini</b>, comme chaque, plusieurs, certains." },
  { q: "Un élève affirme que « sa » est un pronom dans « Il prend sa veste ». Quelle aide est la plus pertinente ?", choices: ["Lui dire de l’apprendre par cœur", "Lui faire observer que « sa » est devant un nom et peut être remplacé par « la » ou « une » : c’est un déterminant possessif", "Lui expliquer que « sa » est un adjectif"], answer: 1, expl: "On s’appuie sur une <b>manipulation</b> : la commutation avec d’autres déterminants (la veste, une veste) montre la classe du mot. Un pronom se placerait devant un verbe, pas devant un nom." },
  { q: "Nature de « comme » dans « Comme il pleuvait, nous sommes restés » :", choices: ["adverbe", "préposition", "conjonction de subordination", "conjonction de coordination"], answer: 2, expl: "« comme » introduit ici une proposition subordonnée de cause (= puisque) : <b>conjonction de subordination</b>. Dans « Comme il est beau ! », ce serait un adverbe exclamatif." }
];

BANK['francais/3'] = [
  { q: "Fonction de « au cinéma » dans « Nous allons au cinéma » :", choices: ["CC de lieu supprimable", "complément essentiel de lieu", "COD", "complément du nom"], answer: 1, expl: "Si on le supprime, « Nous allons » est incomplet : le groupe n’est pas facultatif. La grammaire actuelle parle de <b>complément essentiel de lieu</b> (complément du verbe). Le piège : répondre « CC » à cause de la question « où ? »." },
  { q: "Fonction de « Lire » dans « Lire me détend » :", choices: ["sujet", "COD", "attribut du sujet", "CC de cause"], answer: 0, expl: "C’est <b>lire</b> qui me détend : l’encadrement « C’est… qui » donne le sujet. Un verbe à l’infinitif peut tout à fait être sujet." },
  { q: "Quel est le sujet de « apparaît » : « Au bout du chemin apparaît un cavalier. » ?", answers: ["un cavalier", "cavalier"], expl: "« C’est un cavalier qui apparaît » : le sujet est <b>inversé</b>, placé après le verbe. Ne prends pas le groupe en tête de phrase, « au bout du chemin », qui est un complément de lieu." },
  { q: "Fonction de « un bon médecin » dans « Il reste un bon médecin malgré son âge » :", choices: ["COD", "attribut du sujet", "COI", "complément du nom"], answer: 1, expl: "« rester » est ici un verbe d’état, et « il » et « un bon médecin » désignent la même personne : <b>attribut du sujet</b>. Avec un verbe d’action (il cherche un bon médecin), ce serait un COD." },
  { q: "Fonction de « en » dans « Il en parle souvent » (= de son voyage) :", choices: ["COD", "COI", "CC de lieu", "sujet"], answer: 1, expl: "On parle <b>de</b> quelque chose : le verbe se construit avec une préposition, et « en » reprend « de son voyage ». C’est donc un <b>COI</b>." },
  { q: "Fonction de « du noir » dans « la peur du noir » :", choices: ["COI", "complément du nom", "épithète", "CC de cause"], answer: 1, expl: "« du noir » (= de + le noir) complète le nom « peur » grâce à une préposition : <b>complément du nom</b>. Il appartient au groupe nominal, pas au verbe." },
  { q: "Fonction de « avec un couteau » dans « Il coupe le pain avec un couteau » :", choices: ["CC de manière", "CC de moyen", "COI", "complément du nom"], answer: 1, expl: "« avec quoi ? » → l’outil utilisé : <b>CC de moyen</b>. Il est supprimable et déplaçable. Le CC de manière répondrait à « comment ? » (avec soin, doucement)." },
  { q: "Fonction de « Malgré la fatigue » dans « Malgré la fatigue, il termina la course » :", choices: ["CC de cause", "CC de concession (opposition)", "CC de but", "CC de manière"], answer: 1, expl: "La fatigue aurait dû l’empêcher de finir, et pourtant il finit : c’est une <b>concession</b> (on parle aussi d’opposition). Préposition typique : malgré." },
  { q: "Fonction de « ville lumière » dans « Paris, ville lumière, attire les touristes » :", choices: ["épithète", "apposition", "attribut du sujet", "complément du nom"], answer: 1, expl: "Le groupe est détaché par des virgules et désigne la même réalité que « Paris » : c’est une <b>apposition</b>. Une épithète serait collée au nom, sans virgule." },
  { q: "Par quel pronom remplace-t-on « à ses amis » dans « Il écrit à ses amis » ?", answers: ["leur", "il leur écrit"], expl: "Un COI introduit par « à » et désignant des personnes au pluriel se pronominalise par <b>leur</b> (il leur écrit), sans s. Au singulier, ce serait « lui »." },
  { q: "Pronominalise le COD : « Je regarde ce film. » → Je … regarde.", answers: ["le", "je le regarde"], expl: "Le COD masculin singulier se remplace par <b>le</b>. C’est d’ailleurs ce remplacement par le / la / les qui permet d’identifier un COD." },
  { q: "Quel groupe est le COS dans « Le maître rend les copies aux élèves » ?", answers: ["aux élèves"], expl: "Le verbe a déjà un COD (les copies) ; le second complément introduit par « à » (ici aux = à les) est le <b>COS</b>. On le pronominalise par « leur » : il leur rend les copies." },
  { type: 'vf', q: "Vrai ou faux : on peut déplacer un COD en tête de phrase sans changer la construction ni ajouter de pronom.", answer: 1, expl: "Faux : « *Une pomme, Léa mange » ne fonctionne pas sans reprise (Une pomme, Léa la mange). Le COD n’est ni déplaçable ni supprimable ; c’est ce qui le distingue du CC." },
  { type: 'vf', q: "Vrai ou faux : l’adjectif épithète est toujours placé avant le nom.", answer: 1, expl: "Faux : il peut être avant (une belle maison) ou après (une maison ancienne). Ce qui compte, c’est qu’il soit placé <b>directement</b> à côté du nom, sans virgule ni verbe." },
  { type: 'vf', q: "Vrai ou faux : un complément circonstanciel est, en général, supprimable et déplaçable.", answer: 0, expl: "Vrai : ce sont les deux tests principaux. « Demain, nous partirons » → « Nous partirons demain » → « Nous partirons ». Attention aux compléments essentiels (aller à Paris), qui ne se suppriment pas." },
  { type: 'vf', q: "Vrai ou faux : dans « Ce vélo coûte 300 € », « 300 € » est un COD.", answer: 1, expl: "Faux : on ne peut pas mettre la phrase au passif (*300 € sont coûtés par ce vélo). C’est un <b>complément essentiel</b> (de mesure, de prix), non supprimable mais qui n’est pas un COD." },
  { q: "Fonction de « qui » dans « L’élève qui lit est mon fils » :", choices: ["COD de « lit »", "sujet de « lit »", "complément du nom", "attribut du sujet"], answer: 1, expl: "Dans la relative, « qui » remplace l’élève : <b>l’élève</b> lit. Le pronom relatif « qui » est donc <b>sujet</b> du verbe lit (alors que la relative entière est complément de l’antécédent)." },
  { q: "Fonction de « que » dans « Le gâteau que je mange est délicieux » :", choices: ["sujet de « mange »", "COD de « mange »", "conjonction de subordination sans fonction", "COI de « mange »"], answer: 1, expl: "« que » remplace le gâteau dans la relative : je mange <b>le gâteau</b>. Il est donc <b>COD</b> de mange. C’est pour cela qu’on accorde le participe dans « la tarte que j’ai mangée »." },
  { q: "Un élève dit que « la nuit » est COD dans « Le chat chasse la nuit ». Que lui répondre ?", choices: ["Il a raison : le groupe est juste après le verbe", "Il se trompe : on peut déplacer et supprimer « la nuit » (La nuit, le chat chasse) ; c’est un CC de temps", "Il se trompe : c’est un attribut du sujet"], answer: 1, expl: "La position après le verbe ne suffit pas : on <b>manipule</b>. « La nuit » est déplaçable et supprimable, et répond à « quand ? » : c’est un CC de temps. Un COD ne se déplacerait pas." },
  { q: "Fonction de « vivement » dans « Il répond vivement » ?", answers: ["CC de manière", "complément circonstanciel de manière", "CCM", "complément de manière"], expl: "« Il répond comment ? » → vivement. Cet adverbe est <b>CC de manière</b> : supprimable (Il répond) et déplaçable. Ne confonds pas sa nature (adverbe) et sa fonction." }
];

BANK['francais/4'] = [
  { q: "Type de la phrase : « Comme ce paysage est beau ! »", choices: ["déclaratif", "interrogatif", "injonctif", "exclamatif"], answer: 3, expl: "La phrase exprime une émotion (l’admiration), avec « comme » exclamatif et le point d’exclamation : type <b>exclamatif</b>." },
  { q: "« Est-ce que tu viens ce soir ? » est une interrogation :", choices: ["totale", "partielle", "indirecte"], answer: 0, expl: "On peut y répondre par oui ou par non : interrogation <b>totale</b>. Une interrogation partielle porte sur un élément (qui ? où ? quand ?)." },
  { q: "Forme de la phrase « Il faut que tu partes » :", choices: ["personnelle", "impersonnelle", "passive", "emphatique"], answer: 1, expl: "Le « il » de « il faut » ne désigne personne et ne peut être remplacé par aucun nom : forme <b>impersonnelle</b>. Ne le confonds pas avec le « il » pronom personnel (il chante)." },
  { q: "Combien de propositions dans : « Je pense que tu as raison, mais je préfère attendre. » ?", answers: ["3", "trois"], expl: "Verbes conjugués : pense, as, préfère → <b>3 propositions</b>. « attendre » est à l’infinitif : il ne compte pas. Rappel : autant de propositions que de verbes conjugués." },
  { q: "Combien de propositions dans : « En rentrant de l’école, Léa a vu un chat qui dormait sur le muret. » ?", answers: ["2", "deux"], expl: "Verbes conjugués : a vu, dormait → <b>2 propositions</b>. « En rentrant » est un gérondif, forme non conjuguée : le piège est de le compter." },
  { q: "Mets au passif : « Le vent emporte les feuilles. »", choices: ["Les feuilles ont été emportées par le vent.", "Les feuilles étaient emportées par le vent.", "Les feuilles sont emportées par le vent.", "Le vent est emporté par les feuilles."], answer: 2, expl: "Le COD devient sujet, le sujet devient complément d’agent, et l’auxiliaire être se met au <b>même temps</b> que le verbe actif : emporte (présent) → sont emportées. Le participe s’accorde avec le nouveau sujet." },
  { q: "Quelle phrase ne peut pas être mise au passif ?", choices: ["Le chat attrape la souris.", "Il parle à son voisin.", "Les élèves lisent un conte."], answer: 1, expl: "Seuls les verbes qui ont un <b>COD</b> se mettent au passif. « parler à » se construit avec un COI : *Son voisin est parlé… est impossible." },
  { q: "Nature de la subordonnée : « Il est parti parce qu’il était fatigué. »", choices: ["relative", "complétive", "circonstancielle de cause", "circonstancielle de but"], answer: 2, expl: "Introduite par la conjonction « parce que », elle explique pourquoi il est parti : <b>circonstancielle de cause</b>." },
  { q: "Nature de la subordonnée : « Je ne sais pas si elle viendra. »", choices: ["circonstancielle de condition", "interrogative indirecte", "relative", "circonstancielle de temps"], answer: 1, expl: "Elle correspond à la question « Viendra-t-elle ? » rapportée après « je ne sais pas » : <b>interrogative indirecte</b>, COD du verbe. Le piège : « si » n’exprime pas ici la condition (on ne peut pas le remplacer par « à condition que »)." },
  { q: "Nature de la subordonnée : « Il travaille pour que ses enfants réussissent. »", choices: ["circonstancielle de but", "circonstancielle de conséquence", "complétive", "relative"], answer: 0, expl: "« pour que » exprime l’objectif visé : <b>circonstancielle de but</b>. Le verbe est au subjonctif car le but n’est pas encore réalisé." },
  { q: "Dans « Le livre que tu lis est passionnant », qu’est-ce qui prouve que « que » est un pronom relatif ?", choices: ["Il est placé après un nom", "Il a un antécédent (livre) qu’il remplace dans la subordonnée : tu lis le livre", "Il est suivi d’un verbe conjugué"], answer: 1, expl: "Le test du cours : le relatif <b>remplace un nom</b> dans la subordonnée (tu lis <i>le livre</i>). La conjonction « que » d’une complétive ne remplace rien. Être après un nom ne suffit pas (l’idée que tu partes…)." },
  { q: "Recopie la proposition principale : « Quand il neige, les enfants font un bonhomme. »", answers: ["les enfants font un bonhomme"], expl: "« Quand il neige » est une subordonnée circonstancielle de temps (supprimable). Ce qui reste, <b>les enfants font un bonhomme</b>, est la principale, qui peut exister seule." },
  { q: "Quel mot subordonnant introduit la subordonnée : « Nous sortirons lorsque la pluie cessera. » ?", answers: ["lorsque"], expl: "<b>lorsque</b> est une conjonction de subordination de temps. Il introduit la proposition « lorsque la pluie cessera », CC de temps du verbe sortirons." },
  { type: 'vf', q: "Vrai ou faux : une phrase non verbale (nominale) ne contient aucun verbe conjugué.", answer: 0, expl: "Vrai : « Quel beau temps ! », « Interdiction de stationner. » sont des phrases complètes sans verbe conjugué. Elles ont un sens complet, une majuscule et un point." },
  { type: 'vf', q: "Vrai ou faux : quand le sujet est long, on peut le séparer de son verbe par une virgule.", answer: 1, expl: "Faux : on ne sépare <b>jamais</b> le sujet de son verbe par une seule virgule, même s’il est long (*Les élèves de la classe de CM2, partent). Seule une incise encadrée de deux virgules est possible." },
  { type: 'vf', q: "Vrai ou faux : « Je me demande s’il viendra. » est une phrase de type interrogatif.", answer: 1, expl: "Faux : la question est <b>indirecte</b>, enchâssée dans une phrase qui affirme quelque chose ; la phrase est déclarative et se termine par un point. Seule l’interrogation directe prend un point d’interrogation." },
  { type: 'vf', q: "Vrai ou faux : « Moi, je n’y crois pas. » est une phrase à la forme emphatique.", answer: 0, expl: "Vrai : le pronom « moi » est détaché en tête et repris par « je » ; ce détachement met en relief un élément : c’est l’<b>emphase</b>. Elle est aussi négative : une phrase cumule plusieurs formes." },
  { q: "Les propositions de « Il était fatigué mais il continua » sont :", choices: ["juxtaposées", "coordonnées", "subordonnées"], answer: 1, expl: "Elles sont reliées par la conjonction de coordination « mais » : elles sont <b>coordonnées</b>. Aucune ne dépend de l’autre : chacune pourrait exister seule." },
  { q: "Quelle est la fonction de la subordonnée dans « Je souhaite que tu réussisses » ?", choices: ["COD du verbe souhaite", "sujet", "CC de but", "complément de l’antécédent"], answer: 0, expl: "Je souhaite quoi ? → que tu réussisses. Elle se remplace par « cela » (je souhaite cela) : c’est une complétive <b>COD</b>. Le subjonctif vient du verbe de volonté « souhaiter »." },
  { q: "Quelle est la phrase active correspondant à « La maison sera vendue par l’agence » ?", choices: ["L’agence vendra la maison.", "L’agence a vendu la maison.", "L’agence vendait la maison.", "L’agence vendrait la maison."], answer: 0, expl: "L’auxiliaire « sera » est au futur : le verbe actif est donc au <b>futur</b> (vendra). Le complément d’agent « par l’agence » redevient sujet." }
];

BANK['francais/5'] = [
  { q: "À quel groupe appartient le verbe « haïr » ?", choices: ["1ᵉʳ groupe", "2ᵉ groupe", "3ᵉ groupe"], answer: 1, expl: "Infinitif en -ir et participe présent en -issant (haïssant) : <b>2ᵉ groupe</b>, comme finir. C’est le test du participe présent qui compte, pas seulement la terminaison." },
  { q: "À quel groupe appartient le verbe « partir » ?", choices: ["1ᵉʳ groupe", "2ᵉ groupe", "3ᵉ groupe"], answer: 2, expl: "Participe présent : partant (et non *partissant) : <b>3ᵉ groupe</b>. Le piège : tous les verbes en -ir ne sont pas du 2ᵉ groupe (partir, venir, courir, ouvrir…)." },
  { q: "Conjugue « envoyer » au futur, 1ʳᵉ personne du singulier : j’…", answers: ["enverrai", "j’enverrai", "j'enverrai"], expl: "Le futur d’envoyer est irrégulier : <b>j’enverrai</b> (avec deux r), comme voir → je verrai. On n’écrit pas *j’envoierai." },
  { q: "Conjugue « nettoyer » au présent, 1ʳᵉ personne du singulier : je …", answers: ["nettoie", "je nettoie"], expl: "Les verbes en -oyer changent y en i devant un e muet : <b>je nettoie</b>, tu nettoies, mais nous nettoyons." },
  { q: "Conjugue « commencer » à l’imparfait, 1ʳᵉ personne du singulier : je …", answers: ["commençais", "je commençais"], expl: "Devant a, il faut une cédille pour garder le son [s] : <b>je commençais</b>. En revanche, nous commencions s’écrit sans cédille, car c est suivi de i." },
  { q: "Conjugue « jeter » au présent, 3ᵉ personne du singulier : il …", answers: ["jette", "il jette"], expl: "« jeter » double le t devant un e muet : <b>il jette</b> (mais nous jetons). D’autres verbes en -eter prennent un accent grave à la place : il achète." },
  { q: "Conjugue « mourir » au futur, 3ᵉ personne du singulier : il …", answers: ["mourra", "il mourra"], expl: "Comme courir, mourir prend <b>deux r</b> au futur : il mourra. On entend d’ailleurs le r allongé." },
  { q: "Conjugue « chanter » au passé simple, 1ʳᵉ personne du pluriel :", choices: ["nous chantâmes", "nous chantames", "nous chantions", "nous chantèrent"], answer: 0, expl: "Au passé simple des verbes en -er : -âmes, avec un accent circonflexe. « chantions » est l’imparfait (ou le subjonctif) et « -èrent » la 3ᵉ personne du pluriel." },
  { q: "Subjonctif présent de « pouvoir » : il faut que je …", choices: ["puisse", "peux", "pouvais", "pourrais"], answer: 0, expl: "« pouvoir » a un subjonctif irrégulier : que je <b>puisse</b>, que nous puissions. Les autres formes sont le présent, l’imparfait et le conditionnel de l’indicatif." },
  { q: "Temps de « nous aurions fini » :", choices: ["futur antérieur", "conditionnel passé", "plus-que-parfait", "passé antérieur"], answer: 1, expl: "Auxiliaire au conditionnel présent (aurions) + participe passé : <b>conditionnel passé</b>. Avec « aurons », ce serait le futur antérieur ; avec « avions », le plus-que-parfait." },
  { q: "Temps de « qu’il ait chanté » :", choices: ["subjonctif présent", "subjonctif passé", "passé composé", "passé antérieur"], answer: 1, expl: "Auxiliaire avoir au subjonctif présent (qu’il ait) + participe passé : <b>subjonctif passé</b>. Ne confonds pas « ait » (subjonctif) et « a » (indicatif, passé composé)." },
  { q: "Quel auxiliaire emploie le verbe « tomber » au passé composé ?", choices: ["avoir", "être", "les deux selon le sens"], answer: 1, expl: "« tomber » est un verbe de mouvement / changement d’état : <b>je suis tombé</b>. Retiens la liste : aller, venir, partir, arriver, entrer, sortir, naître, mourir, rester, tomber, devenir…" },
  { q: "Impératif, 2ᵉ personne du singulier de « manger », suivi de « en » :", choices: ["Mange-en !", "Manges-en !", "Mangez-en !"], answer: 1, expl: "À l’impératif, les verbes en -er n’ont pas de s à la 2ᵉ personne du singulier (mange), <b>sauf devant en et y</b> pour faciliter la liaison : manges-en, vas-y. « Mangez-en » est la 2ᵉ personne du pluriel." },
  { q: "Dans « nous chantons », quelle information la terminaison -ons ne porte-t-elle <b>pas</b> ?", choices: ["le temps", "la personne", "le sens du verbe", "le nombre"], answer: 2, expl: "Le <b>sens</b> (l’idée de chanter) est porté par le radical chant-. La terminaison porte le temps, le mode, la personne et le nombre." },
  { type: 'vf', q: "Vrai ou faux : le futur simple et le conditionnel présent se forment sur le même radical.", answer: 0, expl: "Vrai : conditionnel = radical du futur + terminaisons de l’imparfait (je viendrai → je viendrais ; je verrai → je verrais). Si tu connais le futur, tu connais le conditionnel." },
  { type: 'vf', q: "Vrai ou faux : « venir » appartient au 2ᵉ groupe car son infinitif se termine en -ir.", answer: 1, expl: "Faux : son participe présent est « venant » et non *venissant : il est du <b>3ᵉ groupe</b>. Seuls les verbes en -ir qui font -issant sont du 2ᵉ groupe." },
  { type: 'vf', q: "Vrai ou faux : les verbes pronominaux se conjuguent avec l’auxiliaire avoir aux temps composés.", answer: 1, expl: "Faux : ils prennent toujours l’auxiliaire <b>être</b> : je me suis lavé, elle s’est souvenue. C’est une source d’erreurs à l’oral chez les élèves (*je m’ai fait mal)." },
  { type: 'vf', q: "Vrai ou faux : l’impératif ne se conjugue qu’à trois personnes et sans sujet exprimé.", answer: 0, expl: "Vrai : 2ᵉ personne du singulier, 1ʳᵉ et 2ᵉ du pluriel (finis, finissons, finissez), sans pronom sujet. C’est ce qui permet de le reconnaître." },
  { q: "Un élève écrit : « Si je pouvais, je finirai plus tôt. » Quelle est son erreur ?", choices: ["Il aurait dû écrire « Si je pourrais »", "Il a mis le futur au lieu du conditionnel : il faut « je finirais »", "Il n’y a pas d’erreur"], answer: 1, expl: "Après « si + imparfait », la principale est au <b>conditionnel présent</b> : je finirais. Astuce du cours : avec « nous », on entend la différence (nous finirions / nous finirons). Et jamais de conditionnel après si." },
  { q: "Conjugue « savoir » au subjonctif présent : il faut que nous …", answers: ["sachions", "nous sachions"], expl: "« savoir » a un subjonctif irrégulier : que je sache, que nous <b>sachions</b>. Ne le confonds pas avec l’imparfait « nous savions »." }
];

BANK['francais/6'] = [
  { q: "Valeur du présent : « Le train part dans cinq minutes. »", choices: ["énonciation", "futur proche", "vérité générale", "habitude"], answer: 1, expl: "L’indicateur « dans cinq minutes » situe l’action dans l’avenir : présent à valeur de <b>futur proche</b>. Un temps n’indique pas toujours l’époque qu’on attend." },
  { q: "Valeur du présent : « Qui vole un œuf vole un bœuf. »", choices: ["narration", "habitude", "vérité générale", "énonciation"], answer: 2, expl: "Un proverbe énonce une vérité valable en tout temps : présent de <b>vérité générale</b> (on dit aussi gnomique)." },
  { q: "Valeur du présent : « J’arrive à l’instant de Paris. »", choices: ["passé récent", "futur proche", "habitude", "narration"], answer: 0, expl: "« à l’instant » indique que l’action vient juste de se produire : présent à valeur de <b>passé proche (récent)</b>." },
  { q: "Valeur de l’imparfait : « Si j’étais toi, j’accepterais. »", choices: ["description", "habitude", "hypothèse", "action en cours"], answer: 2, expl: "Après « si », l’imparfait n’exprime pas le passé mais une <b>hypothèse</b> (ici irréelle : je ne suis pas toi). Il est suivi du conditionnel dans la principale." },
  { q: "Valeur de l’imparfait : « Je venais vous demander un petit service. »", choices: ["habitude", "politesse (atténuation)", "description", "hypothèse"], answer: 1, expl: "L’action est actuelle, mais l’imparfait la met à distance pour adoucir la demande : imparfait de <b>politesse</b> (ou d’atténuation)." },
  { q: "Que montre le passé composé dans « J’ai lu tout le livre, je peux donc te le prêter » ?", choices: ["une action de premier plan dans un récit littéraire", "une action passée dont le résultat est présent", "une habitude dans le passé"], answer: 1, expl: "La lecture est finie, mais son <b>résultat</b> compte maintenant (je peux le prêter) : c’est la valeur d’accompli du passé composé." },
  { q: "« En 1815, Napoléon est vaincu à Waterloo ; il mourra six ans plus tard à Sainte-Hélène. » Valeur du futur :", choices: ["ordre atténué", "futur historique", "futur proche"], answer: 1, expl: "Dans un récit historique, le futur présente un fait passé comme postérieur au moment raconté : <b>futur historique</b> (ou d’anticipation)." },
  { q: "Valeur du conditionnel : « J’aimerais tant voyager ! »", choices: ["souhait", "futur dans le passé", "information non confirmée", "irréel du passé"], answer: 0, expl: "Le conditionnel exprime ici un désir : valeur de <b>souhait</b>. Il atténue aussi l’affirmation (j’aime → j’aimerais)." },
  { q: "Dans « Il ouvrit la porte, entra et alluma la lumière », le passé simple exprime :", choices: ["des descriptions d’arrière-plan", "des actions successives de premier plan", "des habitudes"], answer: 1, expl: "Trois actions ponctuelles, l’une après l’autre, qui font avancer le récit : c’est le rôle du <b>passé simple</b> (premier plan). L’imparfait servirait au décor." },
  { q: "Complète au bon temps : « Si tu (partir) maintenant, tu arriveras à l’heure. »", answers: ["pars", "tu pars"], expl: "Principale au futur (arriveras) → la subordonnée en si est au <b>présent</b> : si tu pars. C’est le système du possible : si + présent → futur." },
  { q: "Complète : « Si nous avions su, nous (rester) chez nous. »", answers: ["serions restés", "nous serions restés", "serions restées", "nous serions restées"], expl: "Si + plus-que-parfait → <b>conditionnel passé</b> : nous serions restés (irréel du passé). « rester » se conjugue avec être, d’où l’accord avec nous." },
  { q: "Complète : « Si elle travaillait davantage, elle (réussir). »", answers: ["réussirait", "elle réussirait"], expl: "Si + imparfait → <b>conditionnel présent</b> : elle réussirait. Le piège : écrire le futur « réussira » (on entend la différence avec « nous réussirions »)." },
  { q: "Complète au subjonctif : « Je veux que tu (venir). »", answers: ["viennes", "tu viennes"], expl: "Après un verbe de volonté (vouloir), on emploie le <b>subjonctif</b> : que tu viennes. L’action est voulue, pas encore réalisée." },
  { q: "Complète : « Bien qu’il (être) fatigué, il continue. »", answers: ["soit", "il soit"], expl: "« bien que » (concession) est toujours suivi du <b>subjonctif</b> : bien qu’il soit. Erreur fréquente : *bien qu’il est." },
  { type: 'vf', q: "Vrai ou faux : le présent de l’indicatif peut exprimer une action future.", answer: 0, expl: "Vrai : « Je pars demain. » Le présent a plusieurs valeurs : énonciation, habitude, vérité générale, narration, passé ou futur proche." },
  { type: 'vf', q: "Vrai ou faux : après le « si » de condition, on peut employer le conditionnel.", answer: 1, expl: "Faux : jamais de conditionnel après si (*si j’aurais). On met le présent, l’imparfait ou le plus-que-parfait ; le conditionnel va dans la principale." },
  { type: 'vf', q: "Vrai ou faux : dans un récit, l’imparfait sert surtout à exprimer les actions brèves qui font avancer l’histoire.", answer: 1, expl: "Faux : c’est le rôle du passé simple. L’imparfait exprime l’<b>arrière-plan</b> : descriptions, actions en cours, habitudes, commentaires." },
  { type: 'vf', q: "Vrai ou faux : le subjonctif présente l’action comme envisagée plutôt que comme réalisée.", answer: 0, expl: "Vrai : c’est pourquoi on l’emploie après les verbes de volonté, de sentiment, de doute ou d’obligation (il faut que), et après pour que, avant que, bien que." },
  { q: "« Si j’avais des ailes, je volerais. » Ce système hypothétique exprime :", choices: ["le possible dans le futur", "l’irréel du présent", "l’irréel du passé"], answer: 1, expl: "Si + imparfait → conditionnel présent ; et comme je n’ai pas d’ailes, la condition est impossible maintenant : <b>irréel du présent</b>. L’irréel du passé utiliserait le plus-que-parfait (si j’avais eu…)." },
  { q: "Quel temps remplace le plus souvent le passé simple à l’oral ?", choices: ["l’imparfait", "le passé composé", "le plus-que-parfait", "le présent de vérité générale"], answer: 1, expl: "À l’oral et dans les récits à la 1ʳᵉ personne, on raconte au <b>passé composé</b> (je suis entré, j’ai vu). Le passé simple reste le temps du récit écrit littéraire." }
];

BANK['francais/7'] = [
  { q: "Accorde : « Les lettres que tu as (écrire) sont touchantes. »", answers: ["écrites"], expl: "Auxiliaire avoir ; tu as écrit quoi ? « que », mis pour les lettres, placé <b>avant</b> le verbe → accord au féminin pluriel : <b>écrites</b>." },
  { q: "Accorde : « Elles se sont (laver) les cheveux. »", answers: ["lavé"], expl: "On remplace être par avoir : elles ont lavé quoi ? les cheveux, COD placé <b>après</b> → pas d’accord : <b>lavé</b>. Ici « se » est COS (à elles)." },
  { q: "Accorde : « Les fillettes se sont (regarder) dans le miroir. »", answers: ["regardées"], expl: "Elles ont regardé qui ? « se » = elles-mêmes, COD placé avant → accord : <b>regardées</b>." },
  { q: "Accorde : « Ces rois se sont (succéder) sur le trône. »", answers: ["succédé"], expl: "On succède <b>à</b> quelqu’un : ils ont succédé à qui ? « se » est COI, pas COD → pas d’accord : <b>succédé</b>. Même cas que « ils se sont parlé, se sont plu, se sont souri »." },
  { q: "Accorde : « Les prisonnières se sont (enfuir). »", answers: ["enfuies"], expl: "« s’enfuir » est <b>essentiellement pronominal</b> (on ne dit pas *enfuir quelqu’un) : le participe s’accorde avec le sujet → <b>enfuies</b>." },
  { q: "Quel est le pluriel de « pneu » ?", answers: ["pneus", "des pneus"], expl: "Les noms en -eu prennent un x au pluriel (des jeux, des cheveux), <b>sauf</b> pneu, bleu, landau : des <b>pneus</b>." },
  { q: "« La plupart des invités … déjà partis. »", choices: ["est", "sont"], answer: 1, expl: "Avec « la plupart », le verbe se met au <b>pluriel</b> (accord avec le complément : les invités). Le participe « partis » le confirme." },
  { q: "« Toi et moi … au cinéma ce soir. »", choices: ["allez", "allons", "vont"], answer: 1, expl: "Plusieurs sujets de personnes différentes : la 1ʳᵉ personne l’emporte (toi et moi = nous) → <b>allons</b>." },
  { q: "« C’est toi qui … gagné. »", choices: ["a", "as", "ai"], answer: 1, expl: "Le verbe après « qui » s’accorde avec l’antécédent du relatif : toi → 2ᵉ personne : <b>c’est toi qui as gagné</b>. Erreur fréquente : *c’est toi qui a gagné." },
  { q: "Quelle forme est correcte ?", choices: ["des chaussettes oranges", "des chaussettes roses", "des chaussettes marrons", "des chaussettes vert foncés"], answer: 1, expl: "Les adjectifs de couleur issus d’un nom (orange, marron) sont invariables, et les couleurs composées aussi (vert foncé). Mais <b>rose</b> fait partie des exceptions qui s’accordent, avec mauve, fauve et pourpre." },
  { q: "« un pantalon et une veste … »", choices: ["élégantes", "élégants", "élégant"], answer: 1, expl: "Un adjectif qui qualifie un nom masculin et un nom féminin se met au <b>masculin pluriel</b> : élégants." },
  { q: "Quel est le pluriel de « carnaval » ?", choices: ["des carnavaux", "des carnavals"], answer: 1, expl: "Les noms en -al font -aux, <b>sauf</b> bal, carnaval, festival, récital, chacal, régal : des <b>carnavals</b>." },
  { type: 'vf', q: "Vrai ou faux : on écrit « Il est midi et demie ».", answer: 1, expl: "Faux : « demi » placé après le nom s’accorde en <b>genre</b> avec lui. « midi » est masculin, donc <b>midi et demi</b> ; mais « une heure et demie »." },
  { q: "« Quelle belle robe tu as (acheter) ! »", choices: ["acheté", "achetée", "achetées"], answer: 1, expl: "Tu as acheté quoi ? « quelle belle robe », COD placé <b>avant</b> le verbe (phrase exclamative) → accord au féminin singulier : <b>achetée</b>." },
  { q: "« Combien de livres as-tu (lire) cette année ? »", choices: ["lu", "lus", "lue"], answer: 1, expl: "Tu as lu quoi ? « combien de livres », COD placé <b>avant</b> l’auxiliaire avoir → accord au masculin pluriel : <b>lus</b>." },
  { type: 'vf', q: "Vrai ou faux : le participe passé employé avec avoir s’accorde avec le sujet.", answer: 1, expl: "Faux : avec avoir, il ne s’accorde <b>jamais</b> avec le sujet. Il s’accorde seulement avec le COD, et seulement si ce COD est placé avant (elles ont mangé / la pomme qu’elles ont mangée)." },
  { type: 'vf', q: "Vrai ou faux : « Les tartes qu’ils ont préparées » est correctement accordé.", answer: 0, expl: "Vrai : auxiliaire avoir ; ils ont préparé quoi ? « qu’ » mis pour les tartes, placé avant → féminin pluriel : <b>préparées</b>." },
  { type: 'vf', q: "Vrai ou faux : on écrit « deux mille euros », sans s à « mille ».", answer: 0, expl: "Vrai : « mille » est <b>toujours invariable</b> comme déterminant numéral. Ne confonds pas avec « vingt » et « cent », qui prennent un s quand ils sont multipliés et non suivis d’un autre nombre (quatre-vingts, deux cents)." },
  { q: "Un élève écrit : « Les chiens du voisin aboie. » Quelle est l’origine la plus probable de l’erreur ?", choices: ["Il ignore la conjugaison d’aboyer", "Il a accordé le verbe avec le nom le plus proche (voisin) au lieu du sujet (les chiens)", "Il confond le présent et l’imparfait"], answer: 1, expl: "C’est l’erreur classique du <b>sujet éloigné</b> : l’élève accorde avec le mot juste avant le verbe. Remède : chercher le sujet avec « C’est… qui » (ce sont les chiens qui aboient)." },
  { q: "« Elle a fini de (ranger / rangé) sa chambre. »", choices: ["ranger", "rangé"], answer: 0, expl: "Remplace par un verbe du 3ᵉ groupe : « elle a fini de <i>prendre</i> » (et non *de pris) → infinitif : <b>ranger</b>. Après une préposition (de, à, pour), on a un infinitif." }
];

BANK['francais/8'] = [
  { q: "Complète : « Il … vu … film hier. »", choices: ["a … ce", "à … se", "a … se", "à … ce"], answer: 0, expl: "« a » = verbe avoir (il avait vu) ; « ce » est un déterminant démonstratif devant le nom film. « se » ne s’emploie que devant un verbe pronominal (il se lève)." },
  { q: "Complète : « Ils … dit qu’… partirait tôt. »", choices: ["ont … on", "on … ont", "ont … ont", "on … on"], answer: 0, expl: "« ont » = avoir (ils avaient dit) ; « on » est un pronom sujet, remplaçable par « il » (qu’il partirait). Le verbe « partirait » au singulier confirme le choix de « on »." },
  { q: "Complète avec « ce » ou « se » : « … qu’il dit est vrai. »", answers: ["ce", "Ce"], expl: "Devant « que » ou « qui », on écrit <b>ce</b> (ce que, ce qui). « se » est un pronom réfléchi qui accompagne un verbe pronominal (il se trompe)." },
  { q: "Complète avec « sans » ou « s’en » : « Elle … est allée sans rien dire. »", answers: ["s’en", "s'en"], expl: "Il s’agit du verbe <b>s’en aller</b> (se + en) : elle s’en est allée. « sans » est une préposition, contraire de « avec »." },
  { q: "Complète : « … tu arriveras, appelle-moi. »", choices: ["Quand", "Quant", "Qu’en"], answer: 0, expl: "« quand » = lorsque (au moment où tu arriveras). « quant » s’emploie seulement dans « quant à » (en ce qui concerne), et « qu’en » = que + en." },
  { q: "Complète : « Il est arrivé … qu’elle. »", choices: ["plutôt", "plus tôt"], answer: 1, expl: "On peut dire « plus tard qu’elle » : c’est une idée de temps → <b>plus tôt</b>. « plutôt » signifie « de préférence »." },
  { q: "Complète : « … sont tes amis préférés ? »", choices: ["Quels", "Qu’elles", "Quelles"], answer: 0, expl: "On ne peut pas dire « qu’ils sont tes amis » : c’est le déterminant (ou adjectif) interrogatif, accordé avec « amis », masculin pluriel → <b>Quels</b>." },
  { q: "Complète : « Je … crois pas du tout. »", choices: ["ni", "n’y"], answer: 1, expl: "On reconnaît ne + y (je crois à cela → je n’y crois pas) : <b>n’y</b>. « ni » sert à coordonner dans une négation (ni pain ni eau)." },
  { q: "Complète : « Tu … m’aider à porter ce carton ? »", choices: ["peu", "peut", "peux"], answer: 2, expl: "On peut dire « tu pouvais » : verbe pouvoir, 2ᵉ personne du singulier → <b>peux</b> (avec x). « peut » est la 3ᵉ personne, « peu » un adverbe de quantité." },
  { q: "Complète avec « ou » ou « où » : « Il ne sait pas … aller. »", answers: ["où"], expl: "On ne peut pas dire « ou bien » : il s’agit du lieu → <b>où</b>, avec un accent grave." },
  { q: "Quelle orthographe est correcte ?", choices: ["un bombon", "un bonbon", "un bonnbon"], answer: 1, expl: "Normalement, on écrit m devant m, b, p. Mais <b>bonbon</b> est une exception à retenir, comme bonbonne, néanmoins et embonpoint." },
  { q: "Quelle orthographe est correcte ?", choices: ["il a recu", "il a reçu", "il a ressu"], answer: 1, expl: "Devant a, o, u, la lettre c se lit [k] : pour obtenir [s], il faut la <b>cédille</b> : reçu (comme garçon)." },
  { q: "Quelle orthographe est correcte ?", choices: ["nous nagons", "nous nageons", "nous najons"], answer: 1, expl: "Devant o, le g se lit [g] : on ajoute un e pour garder le son [ʒ] → <b>nous nageons</b> (comme nous mangeons, un pigeon)." },
  { q: "Quelle orthographe est correcte ?", choices: ["la moitiée", "la moitié", "l’amitiée"], answer: 1, expl: "Les noms féminins en -tié s’écrivent <b>sans e final</b> : la moitié, l’amitié, la pitié (comme ceux en -té : la liberté)." },
  { q: "Par quel verbe de la même famille peut-on justifier la lettre finale muette de « tricot » ?", answers: ["tricoter", "tricoteuse", "tricotage"], expl: "Dans <b>tricoter</b>, le t s’entend : il justifie le t muet de tricot. La famille de mots (ou le féminin) est la stratégie à enseigner pour les lettres muettes." },
  { type: 'vf', q: "Vrai ou faux : dans « Ils sont partis avec leurs valises », « leurs » est un pronom.", answer: 1, expl: "Faux : « leurs » est placé devant le nom valises : c’est un <b>déterminant possessif</b>, qui s’accorde (valises au pluriel). Le pronom « leur », lui, se place devant un verbe et ne prend jamais de s." },
  { type: 'vf', q: "Vrai ou faux : pour choisir entre « a » et « à », on essaie de remplacer par « avait ».", answer: 0, expl: "Vrai : si on peut dire « avait », c’est le verbe avoir (il a faim → il avait faim). Sinon, c’est la préposition « à » (il va à l’école)." },
  { type: 'vf', q: "Vrai ou faux : le premier e de « exercice » ne prend pas d’accent parce qu’il est suivi d’un x.", answer: 0, expl: "Vrai : on ne met pas d’accent sur le e devant une consonne double ou un x (belle, exercice, examen) : le e s’y prononce déjà [ɛ]." },
  { type: 'vf', q: "Vrai ou faux : « poison » et « poisson » se prononcent de la même façon.", answer: 1, expl: "Faux : entre deux voyelles, un seul s se lit [z] : poison [pwazɔ̃]. Pour obtenir [s], il faut doubler : poisson [pwasɔ̃]." },
  { q: "Un élève écrit : « Il ses trompé. » Quelle correction et quelle stratégie proposer ?", choices: ["« Il c’est trompé » : on remplace par « cela est »", "« Il s’est trompé » : c’est le verbe pronominal se tromper (au présent : il se trompe)", "« Il ces trompé » : on ajoute « -là »"], answer: 1, expl: "« se tromper » est pronominal : au passé composé, il s’est trompé. Pour vérifier, l’élève conjugue au présent (il <b>se</b> trompe) : s’il retrouve « se », il écrit <b>s’est</b>." }
];

BANK['francais/9'] = [
  { q: "Quel est le préfixe de « illisible » ?", answers: ["il", "il-"], expl: "il- + lis + -ible : le préfixe <b>il-</b> est une variante de in- (négation) devant un l, comme im- devant m, b, p et ir- devant r (irréel)." },
  { q: "Quel est le suffixe de « jardinier » ?", answers: ["ier", "-ier"], expl: "jardin + <b>-ier</b> : ce suffixe désigne souvent un métier (pâtissier, policier). Il transforme ici un nom en un autre nom (l’agent)." },
  { q: "Forme l’antonyme de « légal » à l’aide d’un préfixe.", answers: ["illégal"], expl: "Devant un l, le préfixe négatif in- devient il- et on double le l : <b>illégal</b> (comme illisible, illogique)." },
  { q: "Quel est l’hyperonyme commun de « rose, tulipe, marguerite » ?", answers: ["fleur", "fleurs", "une fleur", "les fleurs"], expl: "<b>fleur</b> est le terme générique (hyperonyme) ; rose, tulipe, marguerite sont ses hyponymes. Ce rapport est très utile pour éviter les répétitions dans un texte." },
  { q: "« Ovni » (objet volant non identifié) est formé par :", choices: ["siglaison", "acronymie", "troncation", "mot-valise"], answer: 1, expl: "C’est un groupe d’initiales qui se <b>prononce comme un mot</b> : un acronyme. Un sigle, lui, s’épelle lettre par lettre (S-N-C-F)." },
  { q: "« Courriel » (courrier + électronique) est :", choices: ["un emprunt", "un mot-valise", "une troncation", "un dérivé par suffixation"], answer: 1, expl: "On fusionne le début d’un mot et la fin d’un autre : <b>mot-valise</b> (comme franglais). C’est aussi un néologisme créé pour remplacer l’anglais e-mail." },
  { q: "« Hippodrome » (du grec <i>hippos</i>, cheval, et <i>dromos</i>, course) est formé par :", choices: ["dérivation", "composition savante", "troncation", "emprunt à l’anglais"], answer: 1, expl: "On assemble deux racines grecques : <b>composition savante</b>, comme biologie ou thermomètre. Connaître quelques racines aide à comprendre les mots scientifiques." },
  { q: "Dans « lentement », le suffixe -ment transforme :", choices: ["un nom en verbe", "un adjectif en adverbe", "un verbe en nom"], answer: 1, expl: "lente (adjectif) + -ment → <b>lentement</b> (adverbe de manière). Les suffixes changent souvent la classe du mot, contrairement aux préfixes." },
  { q: "Quel mot n’appartient <b>pas</b> à la famille de « terre » ?", choices: ["terrain", "atterrir", "terrible", "terrestre"], answer: 2, expl: "« terrible » vient du latin <i>terrere</i> (effrayer), comme terreur : il n’a rien à voir avec la terre. Une ressemblance de forme ne suffit pas, il faut un lien de sens." },
  { q: "« La souris de l’ordinateur » / « la souris attrapée par le chat » : il s’agit de…", choices: ["homonymie", "polysémie", "paronymie", "synonymie"], answer: 1, expl: "C’est le même mot, avec un sens figuré né d’une ressemblance de forme : <b>polysémie</b>, une seule entrée dans le dictionnaire. Pour des homonymes, il n’y a aucun lien de sens." },
  { q: "« le couvent » (monastère) / « les poules couvent » :", choices: ["synonymes", "homographes", "paronymes", "antonymes"], answer: 1, expl: "Ces deux mots s’écrivent pareil mais n’ont ni le même sens ni la même prononciation ([kuvɑ̃] / [kuv]) : ce sont des <b>homographes</b>." },
  { q: "Quelle est la connotation la plus fréquente du mot « colombe » ?", choices: ["la paix", "la guerre", "la vitesse"], answer: 0, expl: "La dénotation est un oiseau ; la <b>connotation</b>, sens culturel ajouté, est la paix (la colombe de Picasso). Les connotations sont essentielles pour analyser un texte." },
  { q: "Quel mot appartient au registre soutenu ?", choices: ["une baraque", "une maison", "une demeure"], answer: 2, expl: "« baraque » est familier, « maison » courant, « <b>demeure</b> » soutenu. Le registre dépend de la situation de communication." },
  { q: "« écouter » et « ausculter » viennent du même mot latin. Lequel est de formation savante ?", choices: ["écouter", "ausculter"], answer: 1, expl: "« écouter » a évolué oralement pendant des siècles (formation populaire, très transformé) ; « <b>ausculter</b> » a été repris tardivement au latin écrit, d’où sa forme proche du latin <i>auscultare</i>." },
  { q: "Le suffixe -âtre dans « verdâtre » exprime :", choices: ["un diminutif", "une valeur péjorative", "une possibilité", "une action"], answer: 1, expl: "-âtre donne une nuance <b>péjorative</b> (un vert pas franc, peu agréable), comme dans bleuâtre ou douceâtre. Le diminutif serait -et / -ette." },
  { type: 'vf', q: "Vrai ou faux : un préfixe change généralement la classe grammaticale du mot.", answer: 1, expl: "Faux : faire → refaire reste un verbe, possible → impossible reste un adjectif. C’est le <b>suffixe</b> qui change souvent la classe." },
  { type: 'vf', q: "Vrai ou faux : dans le dictionnaire, un mot polysémique fait l’objet d’une seule entrée.", answer: 0, expl: "Vrai : ses différents sens sont numérotés dans la même entrée. Les homonymes, eux, ont des entrées séparées, car ce sont des mots différents." },
  { type: 'vf', q: "Vrai ou faux : l’élément « chrono- » vient du grec et signifie « temps ».", answer: 0, expl: "Vrai : chronologie, chronomètre, synchrone. Le grec fournit une grande partie du vocabulaire scientifique (télé = loin, phone = son, graphe = écrire)." },
  { type: 'vf', q: "Vrai ou faux : « algèbre » est un emprunt à l’anglais.", answer: 1, expl: "Faux : « algèbre » vient de l’<b>arabe</b> (al-jabr). Le français a emprunté à de nombreuses langues : arabe, italien, anglais (week-end)…" },
  { q: "Pour aider un élève qui écrit « gran » au lieu de « grand », quelle démarche est la plus efficace ?", choices: ["Lui faire recopier le mot dix fois", "Lui faire chercher le féminin ou un mot de la même famille (grande, grandir) où la lettre s’entend", "Lui dire que les lettres muettes sont imprévisibles"], answer: 1, expl: "La lettre finale muette se retrouve souvent grâce au <b>féminin</b> ou à la <b>famille de mots</b> : grande, grandir font entendre le d. On rend l’orthographe raisonnée plutôt que de la faire mémoriser à l’aveugle." }
];
